/**
 * Durable Slack follow-up nudge store (Benny-style).
 *
 * Mid-turn inject and boundary resume share one exactly-once contract:
 * pending nudges rename into delivered/ keyed by source message ts.
 */
import { createHash, randomBytes } from "node:crypto";
import { mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { isRecord } from "../../internal/is-record.js";
function isSlackNudgeRecord(value) {
    return (isRecord(value) &&
        typeof value.id === "string" &&
        typeof value.sourceTs === "string" &&
        typeof value.text === "string");
}
/**
 * Map an arbitrary key onto a single path segment under the store root.
 * Rejects empty / `.` / `..` and strips remaining dots so path traversal
 * cannot escape `<stateRoot>/slack-nudges` (or `slack-asks`).
 */
function safeKey(continuationKey) {
    const trimmed = continuationKey.trim();
    if (trimmed === "" || trimmed === "." || trimmed === "..") {
        return "_empty";
    }
    const sanitized = trimmed
        .replace(/[^a-zA-Z0-9._-]+/g, "_")
        .replace(/^\.+/, "")
        .replace(/\.+/g, "_")
        .slice(0, 180);
    if (sanitized === "" || sanitized === "." || sanitized === "..") {
        return "_empty";
    }
    return sanitized;
}
function contentHash(text) {
    return createHash("sha256").update(text).digest("hex").slice(0, 16);
}
function newNudgeId() {
    return `nudge_${randomBytes(8).toString("hex")}`;
}
export function formatSlackFollowupNudgeBlock(nudges) {
    if (nudges.length === 0) {
        return undefined;
    }
    const lines = [
        "<slack_followup>",
        "New Slack follow-up(s) arrived while you were working. Incorporate them before your final reply. If an ask was already answered in-thread, ack briefly instead of re-answering.",
        "",
    ];
    for (const nudge of nudges) {
        const who = nudge.author === undefined || nudge.author === "" ? "someone" : nudge.author;
        lines.push(`- ${who} @ ${nudge.sourceTs}:`);
        lines.push(nudge.text.trim() === "" ? "(empty)" : nudge.text.trim());
        lines.push("");
    }
    lines.push("</slack_followup>");
    return lines.join("\n").trimEnd();
}
/**
 * Filesystem nudge store under `<root>/<continuation>/pending|delivered`.
 */
export class SlackNudgeStore {
    constructor(rootDir) {
        this.rootDir = rootDir;
    }
    continuationDir(continuationKey) {
        return join(this.rootDir, safeKey(continuationKey));
    }
    pendingDir(continuationKey) {
        return join(this.continuationDir(continuationKey), "pending");
    }
    deliveredDir(continuationKey) {
        return join(this.continuationDir(continuationKey), "delivered");
    }
    deliveredPath(continuationKey, sourceTs) {
        return join(this.deliveredDir(continuationKey), safeKey(sourceTs));
    }
    async append(input) {
        const continuationKey = input.continuationKey.trim();
        const sourceTs = input.sourceTs.trim();
        const text = input.text.trim();
        if (continuationKey === "" || sourceTs === "" || text === "") {
            return false;
        }
        if (await this.isDelivered(continuationKey, sourceTs)) {
            return false;
        }
        const pending = await this.listPending(continuationKey);
        const hash = contentHash(text);
        if (pending.some((item) => item.sourceTs === sourceTs || item.contentHash === hash)) {
            return false;
        }
        const record = {
            id: newNudgeId(),
            continuationKey,
            sourceTs,
            text,
            ...(input.author === undefined || input.author === "" ? {} : { author: input.author }),
            createdAt: new Date().toISOString(),
            contentHash: hash,
        };
        const dir = this.pendingDir(continuationKey);
        await mkdir(dir, { recursive: true });
        const target = join(dir, `${record.id}.json`);
        const tmp = `${target}.${process.pid}.tmp`;
        await writeFile(tmp, `${JSON.stringify(record)}\n`, "utf8");
        await rename(tmp, target);
        return true;
    }
    async listPending(continuationKey) {
        const dir = this.pendingDir(continuationKey);
        let names;
        try {
            names = await readdir(dir);
        }
        catch {
            return [];
        }
        const records = [];
        for (const name of names) {
            if (!name.endsWith(".json")) {
                continue;
            }
            try {
                const raw = await readFile(join(dir, name), "utf8");
                const parsed = JSON.parse(raw);
                if (isSlackNudgeRecord(parsed)) {
                    records.push(parsed);
                }
            }
            catch {
                // Skip corrupt pending files.
            }
        }
        records.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
        return records;
    }
    async isDelivered(continuationKey, sourceTs) {
        if (continuationKey.trim() === "" || sourceTs.trim() === "") {
            return false;
        }
        try {
            await readFile(this.deliveredPath(continuationKey, sourceTs), "utf8");
            return true;
        }
        catch {
            return false;
        }
    }
    async hasUndelivered(continuationKey) {
        return (await this.listPending(continuationKey)).length > 0;
    }
    /**
     * How many follow-ups have reached the agent on this thread. Monotonic
     * within a continuation, so a caller can spot a delivery by comparing two
     * readings — unlike {@link hasUndelivered}, which races the carrier: both
     * run at the same tool boundary, and a queued nudge drained before the
     * first reading never looks pending at all.
     */
    async deliveredCount(continuationKey) {
        if (continuationKey.trim() === "") {
            return 0;
        }
        try {
            return (await readdir(this.deliveredDir(continuationKey))).length;
        }
        catch {
            return 0;
        }
    }
    /**
     * Atomically move all pending nudges to delivered and return them.
     * Already-delivered source ts values are dropped (exactly-once).
     */
    async drainForInject(continuationKey) {
        const pending = await this.listPending(continuationKey);
        if (pending.length === 0) {
            return [];
        }
        await mkdir(this.deliveredDir(continuationKey), { recursive: true });
        const delivered = [];
        for (const record of pending) {
            const pendingPath = join(this.pendingDir(continuationKey), `${record.id}.json`);
            if (await this.isDelivered(continuationKey, record.sourceTs)) {
                await rm(pendingPath, { force: true });
                continue;
            }
            const dest = this.deliveredPath(continuationKey, record.sourceTs);
            const tmp = `${dest}.${process.pid}.tmp`;
            try {
                await writeFile(tmp, `${JSON.stringify(record)}\n`, "utf8");
                await rename(tmp, dest);
                await rm(pendingPath, { force: true });
                delivered.push(record);
            }
            catch {
                await rm(tmp, { force: true }).catch(() => { });
                // Race: another drain won — treat as delivered.
                await rm(pendingPath, { force: true }).catch(() => { });
            }
        }
        return delivered;
    }
    /**
     * Settle a follow-up the caller is handling itself, so the carrier cannot
     * inject it again. Used by the boundary drain: a follow-up the carrier did
     * not reach becomes the next turn's prompt, and without this its pending
     * record survives into that turn and gets injected on top of the ask it
     * already is.
     */
    async markDelivered(continuationKey, sourceTs) {
        const key = continuationKey.trim();
        const ts = sourceTs.trim();
        if (key === "" || ts === "") {
            return;
        }
        const pending = await this.listPending(key);
        const record = pending.find((item) => item.sourceTs === ts);
        await mkdir(this.deliveredDir(key), { recursive: true });
        const dest = this.deliveredPath(key, ts);
        const tmp = `${dest}.${process.pid}.tmp`;
        try {
            await writeFile(tmp, `${JSON.stringify(record ?? { continuationKey: key, sourceTs: ts })}\n`, "utf8");
            await rename(tmp, dest);
        }
        catch {
            await rm(tmp, { force: true }).catch(() => { });
        }
        if (record !== undefined) {
            await rm(join(this.pendingDir(key), `${record.id}.json`), {
                force: true,
            }).catch(() => { });
        }
    }
    async clear(continuationKey) {
        await rm(this.continuationDir(continuationKey), {
            recursive: true,
            force: true,
        });
    }
    /** Drain + format for tool/hook inject. */
    async drainFormatted(continuationKey) {
        return formatSlackFollowupNudgeBlock(await this.drainForInject(continuationKey));
    }
}
/**
 * Durable ask claim store: one marker per `channelId:message.ts` so delayed
 * Slack redelivery cannot start a second full answer.
 */
export class SlackAskDedupeStore {
    constructor(rootDir) {
        this.rootDir = rootDir;
    }
    markerPath(channelId, messageTs) {
        return join(this.rootDir, `${safeKey(channelId)}__${safeKey(messageTs)}.claimed`);
    }
    /** Returns true the first time this ask is claimed. */
    async tryClaim(channelId, messageTs) {
        if (channelId.trim() === "" || messageTs.trim() === "") {
            return false;
        }
        const path = this.markerPath(channelId, messageTs);
        await mkdir(this.rootDir, { recursive: true });
        try {
            await writeFile(path, `${new Date().toISOString()}\n`, {
                encoding: "utf8",
                flag: "wx",
            });
            return true;
        }
        catch {
            return false;
        }
    }
    /** Drop a claim so a failed delivery can be retried. */
    async release(channelId, messageTs) {
        if (channelId.trim() === "" || messageTs.trim() === "") {
            return;
        }
        await rm(this.markerPath(channelId, messageTs), { force: true });
    }
    async wasClaimed(channelId, messageTs) {
        try {
            await readFile(this.markerPath(channelId, messageTs), "utf8");
            return true;
        }
        catch {
            return false;
        }
    }
}
